// Pierwszy indeks i w [0, n) z a[i] >= x (jak std::lower_bound); n, gdy nie ma.
int lowerBound(const vector<int>& a, int x) {
    int lo = 0, hi = a.size();          // odpowiedź zawsze w [lo, hi]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;   // lo <= mid < hi
        if (a[mid] >= x) hi = mid;      // mid może być odpowiedzią
        else lo = mid + 1;              // a[mid] < x, odpowiedź na prawo
    }
    return lo;
}
// Pierwszy indeks i z a[i] > x (jak std::upper_bound).
int upperBound(const vector<int>& a, int x) {
    int lo = 0, hi = a.size();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > x) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

