pair<int, int> pairWithSum(const vector<long long>& a, long long x) {
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        long long s = a[l] + a[r];
        if (s == x) return {l, r};
        if (s < x) l++;       // potrzebujemy większej sumy
        else r--;             // potrzebujemy mniejszej
    }
    return {-1, -1};
