int shortestWithAll(const vector<int>& a, int k) {   // kolory 0..k-1
    vector<int> cnt(k, 0);
    int present = 0, best = INT_MAX, l = 0;
    for (int r = 0; r < (int)a.size(); r++) {
        if (cnt[a[r]]++ == 0) present++;
        while (present == k) {
            best = min(best, r - l + 1);
            if (--cnt[a[l]] == 0) present--;
            l++;
        }
    }
    return best == INT_MAX ? -1 : best;
}

