// Ile odcinków poziomych przecina każdy z pionowych — miotła po x, Fenwick po y (skompresowanym).
// poziome: (x1, x2, y), pionowe: (x, y1, y2); współrzędne y już skompresowane do [1, m].
long long countCrossings(const vector<array<int, 3>>& horizontal, const vector<array<int, 3>>& vertical, int m) {
    vector<int> bit(m + 1, 0);
    auto add = [&](int i, int v) { for (; i <= m; i += i & -i) bit[i] += v; };
    auto sum = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };
    vector<array<int, 4>> ev;                  // (x, typ, a, b): typ 0 = start poziomego, 1 = pionowy, 2 = koniec poziomego
    for (auto [x1, x2, y] : horizontal) { ev.push_back({x1, 0, y, 0}); ev.push_back({x2, 2, y, 0}); }
    for (auto [x, y1, y2] : vertical) ev.push_back({x, 1, y1, y2});
    sort(ev.begin(), ev.end());
    long long total = 0;
    for (auto [x, type, a, b] : ev) {
        if (type == 0) add(a, 1);
        else if (type == 2) add(a, -1);
        else total += sum(b) - sum(a - 1);     // aktywne poziome z y w [y1, y2]
    }
    return total;
}

