// Wszystkie sumy podzbiorów elementów a[from..to)
vector<long long> subsetSums(const vector<long long>& a, int from, int to) {
    vector<long long> sums = {0};
    for (int i = from; i < to; i++) {
        int sz = sums.size();
        for (int j = 0; j < sz; j++) sums.push_back(sums[j] + a[i]);   // podwajamy listę
